urlset:
{% for crop in crops %}

    {{ url_for('view_crop', crop_id=crop.id, _external=True) }}

        {{ crop.image_url if crop.image_url.startswith('http') else url_for('static', filename=(crop.image_url.replace('/static/', '') if crop.image_url.startswith('/static/') else crop.image_url), _external=True) }}
        {{ crop.name }}
        {{ truncate_meta_description(crop.description or crop.name, 100) }}


{% endfor %}
{% for article in articles %}

    {{ url_for('view_article', article_id=article.id, _external=True) }}

        {{ article.featured_image if article.featured_image.startswith('http') else url_for('static', filename=(article.featured_image.replace('/static/', '') if article.featured_image.startswith('/static/') else article.featured_image), _external=True) }}
        {{ article.title }}
        {{ truncate_meta_description(article.summary or article.content or article.title, 100) }}


{% endfor %}
